// ── Position helper (for character map) ────────────────────────────────────
function charPos(text, i) {
  if(i===0) return 0;
  if(i===text.length-1) return 2;
  return (text[i-1]===' ') ? 0 : (text[i+1]===' '||text[i+1]==='.'||text[i+1]==='۔'||text[i+1]==='،') ? 2 : 1;
}


