function normalizeUrduChars(text) {
  return text.split('').map(function(c) { return URDU_CHAR_NORM[c] || c; }).join('');
}

// ── Diacritic stripping ─────────────────────────────────────────────────────
// Removes Urdu/Arabic diacritics (harakat) that break dictionary lookup
// Ported from urduhack/preprocessing/util.py remove_diacritics()
function removeDiacritics(text) {
  return text.normalize('NFC')
    .replace(/[\u0610-\u061A\u064B-\u065F\u0670\u06D6-\u06DC\u06DF-\u06E4\u06E7\u06E8\u06EA-\u06ED]/g, '')
    .replace(/[\u200C\u200D\u200B\uFEFF]/g, '')
    .replace(/\s+/g, ' ').trim();
}

// ── Core: urduToRoman ───────────────────────────────────────────────────────
function urduToRoman(text) {
  if(!text) return '';
  text = String(text);
  // Normalize Arabic-variant characters to canonical Urdu (urduhack)
  text = normalizeUrduChars(text);
  // Strip diacritics and zero-width chars before lookup
  text = removeDiacritics(text);
  // Word-level lookup first (more accurate)
  var words = text.split(/s+/);
  var out = words.map(function(w) {
    var clean = w.replace(/[،۔؟!]/g,'').trim();
    if(!clean) return w;
    // Try exact word lookup
    if(UR2RU[clean]) return UR2RU[clean];
    // Try character-level fallback
    var result = '', i = 0;
    while(i < clean.length) {
      var ch = clean[i];
      if(UR_CHAR_MAP[ch]) {
        var pos = charPos(clean, i);
        var maps = UR_CHAR_MAP[ch];
        result += maps.length > 1 ? maps[pos] : maps[0];
      } else {
        result += ch; // keep as-is (English letters, digits, punct)
      }
      i++;
    }
    return result || w;
  });
  return out.join(' ');
}

// ── Core: romanToUrdu ───────────────────────────────────────────────────────
function romanToUrdu(text) {
  if(!text) return '';
  text = String(text).trim();
  var words = text.split(/s+/);
  var out = words.map(function(w) {
    var clean = w.replace(/[.,?!]/g,'').toLowerCase();
    if(!clean) return w;
    // 1. Exact word lookup
    if(RU2UR[clean]) return RU2UR[clean];
    // 2. Try common variant spellings
    var variants = [
      clean.replace(/ee$/,'i'), clean.replace(/oo$/,'u'),
      clean.replace(/aa$/,'a'), clean.replace(/ph/,'f'),
      clean+'a', clean+'i', clean+'o'
    ];
    for(var vi=0; vi<variants.length; vi++) {
      if(RU2UR[variants[vi]]) return RU2UR[variants[vi]];
    }
    // 3. Character-level fallback using RO_CHAR_MAP (uppercase matching)
    var upper = clean.toUpperCase();
    var result = '', i = 0;
    while(i < upper.length) {
      // Try 2-char digraphs first (CH, KH, SH, GH, AA, AH)
      var di = upper.slice(i, i+2);
      if(RO_CHAR_MAP[di]) { result += RO_CHAR_MAP[di]; i += 2; continue; }
      var si = upper[i];
      if(RO_CHAR_MAP[si]) { result += RO_CHAR_MAP[si]; }
      else { result += clean[i]; } // keep unknown chars as-is
      i++;
    }
    return result || w;
  });
  return out.join(' ');
}

// ── Lookup helpers ──────────────────────────────────────────────────────────
function lookupRoman(word) {
  return RU2UR[(word||'').toLowerCase().trim()] || null;
}
function lookupUrdu(word) {
  return UR2RU[(word||'').trim()] || null;
}

// ── Tech terms ──────────────────────────────────────────────────────────────
function getTechTerms() { return TECH_TERMS; }

function findTechTerm(query) {
  query = (query||'').toLowerCase().trim();
  if(!query) return [];
  return TECH_TERMS.filter(function(t){
    return t.en.toLowerCase().indexOf(query)>=0 ||
           t.ru.toLowerCase().indexOf(query)>=0 ||
           t.ur.indexOf(query)>=0;
  });
}

// ── English → Urdu/Roman ───────────────────────────────────────────────────
function translateEnToUrdu(word) {
  var q = (word||'').toLowerCase().trim();
  for(var i=0;i<TECH_TERMS.length;i++){
    if(TECH_TERMS[i].en.toLowerCase()===q) return {ur:TECH_TERMS[i].ur, ru:TECH_TERMS[i].ru};
  }
  return null;
}

